details.oldText:
// GLB (Game Library) archive reader for the DOS Raptor shareware data files.
// Reverse-engineered from SOURCE/../GFX/GLBAPI.C — Scott Host's GLB format.
//
// File layout (all multi-byte ints little-endian):
//   [ KEYFILE ]            encrypted with serial "32768GLB"
//   [ IDT: KEYFILE x N ]  each encrypted with the same serial
//   item data blobs at KEYFILE.offset, each optionally encrypted (opt==GLB_ENCODED)
//
// KEYFILE { DWORD opt; DWORD offset; DWORD filesize; CHAR name[16]; }  == 28 bytes

export const SEED = 0x19; // 25
const SERIAL = "32768GLB";

// GLB_DeCrypt from GLBAPI.C, byte-exact.
export function decrypt(keyStr, buf) {
  const key = [];
  for (let i = 0; i < keyStr.length; i++) key.push(keyStr.charCodeAt(i));
  const klen = key.length;
  let kidx = SEED % klen;
  let prev = key[kidx];
  const out = new Uint8Array(buf.length);
  for (let i = 0; i < buf.length; i++) {
    const b = buf[i];
    const d = (b - key[kidx] - prev) & 0xff;
    prev = b;
    out[i] = d;
    if (++kidx >= klen) kidx = 0;
  }
  return out;
}

export function u32(u8, o) {
  return u8[o] | (u8[o + 1] << 8) | (u8[o + 2] << 16) | (u8[o + 3] << 24);
}
export function u16(u8, o) {
  return u8[o] | (u8[o + 1] << 8);
}
export function i16(u8, o) {
  const v = u8[o] | (u8[o + 1] << 8);
  return v >= 0x8000 ? v - 0x10000 : v;
}
export function i32(u8, o) {
  return u32(u8, o) | 0;
}

export function parseKeyfile(dec) {
  return {
    opt: u32(dec, 0),
    offset: u32(dec, 4),
    filesize: u32(dec, 8),
    name: decToString(dec.subarray(12, 28)),
  };
}

function decToString(u8) {
  let s = "";
  for (let i = 0; i < u8.length; i++) {
    if (u8[i] === 0) break;
    s += String.fromCharCode(u8[i]);
  }
  return s;
}

// Opens a GLB file, returns { items: Map<name, {opt, offset, filesize}>, bytes }
export function readGlb(buffer) {
  const bytes = new Uint8Array(buffer);
  const key = new Uint8Array(bytes.buffer, bytes.byteOffset, 28);
  const head = decrypt(SERIAL, key.slice());
  const numItems = u32(head, 4); // KEYFILE.offset field == item count
  const items = new Map();
  for (let i = 0; i < numItems; i++) {
    const off = 28 + i * 28;
    const dec = decrypt(SERIAL, bytes.subarray(off, off + 28));
    const kf = parseKeyfile(dec);
    items.set(kf.name, { opt: kf.opt, offset: kf.offset, filesize: kf.filesize });
  }
  return { bytes, items };
}

export function getItem(glb, name) {
  const meta = glb.items.get(name);
  if (!meta) return null;
  const raw = glb.bytes.subarray(meta.offset, meta.offset + meta.filesize);
  if (meta.opt === 1) {
    return decrypt(SERIAL, raw);
  }
  return raw;
}

