/***************************************************************************
RAP_SetPlayerDiff () - Set Player Difficulty
 ***************************************************************************/
VOID
RAP_SetPlayerDiff (
VOID
)
{
   cur_diff = 0;

   curplr_diff = plr.diff [ cur_game ];

   switch ( curplr_diff )
   {
      case DIFF_0:
         cur_diff |= EB_EASY_LEVEL;
         break;

      case DIFF_1:
         cur_diff |= EB_EASY_LEVEL;
         break;

      default:
      case DIFF_2:
         cur_diff |= EB_EASY_LEVEL;
         cur_diff |= EB_MED_LEVEL;
         break;

      case DIFF_3:
         cur_diff |= EB_EASY_LEVEL;
         cur_diff |= EB_MED_LEVEL;
         cur_diff |= EB_HARD_LEVEL;
         break;
   }
}

